from html import escape as e

REPO = 'https://github.com/annali/AIStudyNote'


def render(notes, headings, categories):
    rows = ''.join(f'''<li class="manage-row"><div><a href="notes/{n['slug']}.html">{e(n['title'])}</a><small>{e(n['category'])} · {n['updated']}</small></div><div class="row-actions"><a href="{REPO}/edit/main/content/{n['slug']}.json">修改 ↗</a><a class="delete-link" href="{REPO}/delete/main/content/{n['slug']}.json">刪除 ↗</a></div></li>''' for n in notes)
    hints = {'核心概念':'分段說明定義、使用情境與容易混淆的邊界。','實作範例':'標示示例或實測，包含輸入、操作、預期結果與檢查。','常見誤解':'指出一個具體誤解，解釋原因並給出正確做法。','動手練習':'提供新情境、要交出的產物與至少兩項通過條件。'}
    fields = ''.join(f'<label>{h}<textarea name="section{i}" rows="4" placeholder="{hints[h]}" required></textarea></label>' for i, h in enumerate(headings))
    options = ''.join(f'<option>{c}</option>' for c in categories)
    return f'''<div class="article-header"><p class="eyebrow">WRITE · REVIEW · PUBLISH</p><h1>讓筆記，繼續生長。</h1><p class="article-summary">新增、修改與刪除內容，保存到你的 GitHub Repository。</p></div>
<div class="workflow-notice"><strong>儲存方式：GitHub 提交</strong><p>表單先產生 JSON；按「複製 JSON」後，再按 GitHub 新增連結，在 GitHub 貼上內容並按 Commit changes。修改與刪除也在 GitHub 確認。需要登入有寫入權限的帳號。提交成功後，GitHub Actions 會重新建置並發布。</p><p>正式自動更新網址：<a href="https://annali.github.io/AIStudyNote/">annali.github.io/AIStudyNote/ ↗</a>。Sites 展示鏡像不會自動同步。表單不會自動儲存，離開前請複製內容。</p><a href="{REPO}/actions">查看發布進度 ↗</a> · <a href="rules.html">閱讀內容規則</a></div>
<section class="manage-section"><h2>已發布筆記 <span class="category">{len(notes)} 篇</span></h2><ul class="manage-list">{rows}</ul></section>
<section class="manage-section"><h2>新增筆記</h2><p>填寫固定欄位，先產生並檢查 JSON，再提交到 GitHub。每個章節可用空白行分段。</p><form id="note-form"><div class="form-columns"><label>標題<input name="title" required maxlength="100"></label><label>筆記網址名稱（選填）<input name="slug" placeholder="可填中文，留空會依標題產生"></label><label>分類<select name="category">{options}</select></label><label>修改日期<input name="updated" type="date" required></label></div><label>摘要<textarea name="summary" rows="2" required></textarea></label><label>標籤（逗號分隔，最多四個）<input name="tags" required placeholder="入門, 提示設計"></label>{fields}<div class="form-columns"><label>來源標題<input name="sourceTitle" required></label><label>來源網址<input name="sourceUrl" type="text" inputmode="url" required placeholder="直接貼上網址，不用輸入 https://"></label></div><button class="primary-button" type="submit">產生筆記 JSON</button></form><p id="form-status" role="status" aria-live="polite"></p><section id="export-panel" hidden><h3>確認後提交</h3><p id="target-file"></p><label>產生的 JSON（唯讀）<textarea id="json-output" rows="16" readonly></textarea></label><button type="button" class="primary-button" id="copy-open">複製 JSON</button><a id="github-new" href="{REPO}/new/main/content" target="_blank" rel="noopener">手動前往 GitHub 新增 ↗</a><p>若無法自動複製，請選取上方 JSON 手動複製。在 GitHub 新檔案中貼上，完成提交後查看 Actions 結果。</p></section></section><script src="assets/manage.js" defer></script>'''
